.dww-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dww-root,.dww-root *,.dww-root *::before,.dww-root *::after{box-sizing:border-box}
.dww-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dww-root img{display:block;border:0;max-width:none}
.dww-root > [data-node-id]{will-change:transform}
.dww-root [hidden]{display:none!important}
.dww-root [data-sh-theme="dark"]{display:none!important}
.dww-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dww-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dww-root .x13{align-content:stretch;display:flex;gap:8px;height:100%;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.dww-root .n1_3652{aspect-ratio:66/66;height:100%;position:relative;border-radius:8px;flex-shrink:0}
.dww-root .x14{position:absolute;inset:0;pointer-events:none;border-radius:8px}
.dww-root .x15{position:absolute;background-color:var(--wa-bg, #f5f7ff);inset:0;border-radius:8px}
.dww-root .x16{position:absolute;inset:0;overflow:hidden;border-radius:8px}
.dww-root .x17{position:absolute;height:158.84%;left:-52.94%;max-width:none;top:-21.51%;width:199.45%}
.dww-root .n1_3653{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:29px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #171d25);font-size:24px;white-space:nowrap;width:126px}
.dww-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dww-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dww-root[data-theme="dark"] [data-name="Input"],.dww-root[data-theme="dark"] [data-name="Select"],.dww-root[data-theme="dark"] [data-name^="Field/ID"],.dww-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dww-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dww-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dww-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dww-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dww-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dww-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dww-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dww-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dww-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dww-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dww-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dww-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dww-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dww-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dww-root[data-theme="dark"] .x15{background-color:var(--wa-surface, #23262d)}
.dww-root[data-theme="dark"] .n1_3653{color:var(--wa-text, #eceef2)}
